    [(0, 3), (1, 2), (2, 2)],  # Job 0
    [(0, 2), (2, 1), (1, 4)],  # Job 1
    [(1, 4), (2, 3)]           # Job 2
]

# Get the number of jobs and tasks
num_jobs = len(jobs_data)
max_tasks = max(len(job) for job in jobs_data)

# Extract machine IDs and durations for each task
machine_ids = []
durations = []
for job in jobs_data:
    job_machine_ids = []
    job_durations = []
    for task in job:
        job_machine_ids.append(task[0])
        job_durations.append(task[1])
    machine_ids.append(job_machine_ids)
    durations.append(job_durations)

# Model definition
model = cp.Model()

# Decision variables
start_times = {}
for job in range(num_jobs):
    for task in range(len(jobs_data[job])):
        start_times[(job, task)] = cp.intvar(0, 100, name=f"start_time_{job}_{task}")

# Constraints
for job in range(num_jobs):
    for task in range(1, len(jobs_data[job])):
        # No task for a job can be started until the previous task for that job is completed
        model += start_times[(job, task)] >= start_times[(job, task - 1)] + durations[job][task - 1]

# Create a list of tasks for each machine
machine_tasks = {}
for job in range(num_jobs):
    for task, (machine_id, duration) in enumerate(jobs_data[job]):
        if machine_id not in machine_tasks:
            machine_tasks[machine_id] = []
        machine_tasks[machine_id].append((job, task, duration))

# A machine can only work on one task at a time
for machine_id, tasks in machine_tasks.items():
    for i in range(len(tasks)):
        for j in range(i + 1, len(tasks)):
            job1, task1, duration1 = tasks[i]
            job2, task2, duration2 = tasks[j]
            model += (start_times[(job1, task1)] + duration1 <= start_times[(job2, task2)]) | (start_times[(job2, task2)] + duration2 <= start_times[(job1, task1)])

# Objective
makespan = cp.intvar(0, 100, name="makespan")
for job in range(num_jobs):
    model += makespan >= start_times[(job, len(jobs_data[job]) - 1)] + durations[job][-1]
model.minimize(makespan)

# Solve and print
if model.solve():
    solution = {'makespan': int(makespan.value())}
    print(json.dumps(solution, indent=4))
else:
    print("No solution found.")
```

