import cpmpy as cp
import json

# Data (optional)
jobs_data = [  # (job_id, task_id) -> (machine_id, duration)
    [(0, 3), (1, 2), (2, 2)],  # Job 0
    [(0, 2), (2, 1), (1, 4)],  # Job 1
    [(1, 4), (2, 3)]           # Job 2
]

# Model definition
model = cp.Model()

# Get the number of jobs and tasks
num_jobs = len(jobs_data)
num_tasks = max(max(task[0] for task in job) for job in jobs_data) + 1
num_machines = max(max(task[1] for task in job) for job in jobs_data) + 1

# Decision Variables
start_time = cp.intvar(0, 1000, shape=(num_jobs, num_tasks), name="start_time")
makespan = cp.intvar(0, 1000, name="makespan")

# Constraints
for job in range(num_jobs):
    for task in range(num_tasks - 1):
        if task < len(jobs_data[job]) - 1:
            model += start_time[job, task + 1] >= start_time[job, task] + jobs_data[job][task][1]

for machine in range(num_machines):
    tasks_on_machine = []
    for job in range(num_jobs):
        for task in range(len(jobs_data[job])):
            if jobs_data[job][task][0] == machine:
                tasks_on_machine.append((job, task))

    if tasks_on_machine:
        for i in range(len(tasks_on_machine)):
            for j in range(i + 1, len(tasks_on_machine)):
                model += cp.Or(
                    start_time[tasks_on_machine[i][0], tasks_on_machine[i][1]] + jobs_data[tasks_on_machine[i][0]][tasks_on_machine[i][1]][1] <= start_time[tasks_on_machine[j][0], tasks_on_machine[j][1]],
                    start_time[tasks_on_machine[j][0], tasks_on_machine[j][1]] + jobs_data[tasks_on_machine[j][0]][tasks_on_machine[j][1]][1] <= start_time[tasks_on_machine[i][0], tasks_on_machine[i][1]]
                )

# Objective
model.minimize(makespan)

# Additional constraints to enforce makespan
for job in range(num_jobs):
    model += makespan >= start_time[job, num_tasks - 1] + jobs_data[job][-1][1]

# Solve and print
if model.solve():
    solution = {'makespan': int(makespan.value())}
    print(json.dumps(solution, indent=4))
else:
    print("No solution found.")
```

