import cpmpy as cp
import json
import numpy as np

# Data
N = 20  # Number of steps to the solution
puzzle_start = [
    [0, 3, 6],
    [2, 4, 8],
    [1, 7, 5]
]

puzzle_end = [
    [1, 2, 3],
    [4, 5, 6],
    [7, 8, 0]
]

# Model definition
model = cp.Model()

# Decision Variables
rows, cols = len(puzzle_start), len(puzzle_start[0])
steps = cp.intvar(0, rows * cols - 1, shape=(N + 1, rows, cols), name="steps")

# Constraints
# Start state
for i in range(rows):
    for j in range(cols):
        model += steps[0, i, j] == puzzle_start[i][j]

# Goal state
for i in range(rows):
    for j in range(cols):
        model += steps[N, i, j] == puzzle_end[i][j]

# Movement constraints
for t in range(N):
    for i in range(rows):
        for j in range(cols):
            # Find the empty tile
            empty_tile = cp.intvar(0, 1, name=f"empty_tile_{t}_{i}_{j}")
            model += (steps[t, i, j] == 0) == empty_tile

            # If the current tile is empty, it can move up, down, left, or right
            if i > 0:
                model += steps[t + 1, i, j] == cp.IfThenElse(empty_tile, steps[t, i - 1, j], steps[t, i, j])
            elif j > 0:
                model += steps[t + 1, i, j] == cp.IfThenElse(empty_tile, steps[t, i, j - 1], steps[t, i, j])
            else:
                model += steps[t + 1, i, j] == steps[t, i, j]

            # If the current tile is not empty, it can move to the empty tile
            if i < rows - 1:
                model += steps[t + 1, i + 1, j] == cp.IfThenElse(empty_tile, steps[t, i, j], steps[t, i + 1, j])
            elif j < cols - 1:
                model += steps[t + 1, i, j + 1] == cp.IfThenElse(empty_tile, steps[t, i, j], steps[t, i, j + 1])
            else:
                model += steps[t + 1, i, j] == steps[t, i, j]

# Objective (optional)
# model.maximize(cp.sum(steps))

# Solve and print
if model.solve():
    solution = {'steps': steps.value().tolist()}
    print(json.dumps(solution, indent=4))
else:
    print("No solution found.")
```

