        if i == j:
            model += adj_matrix[i, j] == 0  # no self-loops
        elif i < j:
            model += adj_matrix[i, j] == adj_matrix[j, i]  # symmetric matrix

# Constraints for the degree sequences
for seq in degree_sequences:
    model += cp.sum([adj_matrix[i, j] for j in range(N) for i in range(N) if i < j]) == sum(seq) / 2  # sum of degrees
    for i in range(N):
        model += cp.sum([adj_matrix[i, j] for j in range(N)]) == seq[i]  # degree of each vertex

    # Constraints for diamond-free graph
    for i in range(N):
        for j in range(N):
            for k in range(N):
